                    if (selectedId) {
                      try {
                        const response = await apiRequest(
                          "http://127.0.0.1:8000/api/entreprise/entreprises/set-active/", // Correction de l'URL ici
                          {
                            method: "POST",
                            body: JSON.stringify({ entreprise_id: selectedId }),
                          }
