                        alert("Entreprise active changée avec succès !"); // Revert to alert()
                      } catch (error) {
                        console.error(
                          "Erreur lors du changement d'entreprise active:",
                          error
                        );
                        alert(
                          `Échec du changement d'entreprise active: ${error.message}`
