          </form>
        </div>
      </div>
    </div>
  );

  const renderModal = () => (
    <div
      className={`modal fade ${showModal ? "show" : ""}`}
      style={{ display: showModal ? "block" : "none" }}
      tabIndex="-1"
    >
      <div className="modal-dialog modal-lg">
        <div className="modal-content">
          <div className="modal-header">
            <h5 className="modal-title">Aperçu du document</h5>
            <button
              type="button"
              className="btn-close"
              onClick={() => setShowModal(false)}
            ></button>
          </div>
          <div className="modal-body">
            {selectedDocument && (
              <div>
                <h6>{selectedDocument.titre}</h6>
                <p className="text-muted">
                  Date de publication : {selectedDocument.date_publication}
                </p>
                <p className="text-muted">Source : {selectedDocument.source}</p>
                <p className="text-muted">
                  Type : {selectedDocument.type_publication}
                </p>
                <p className="text-muted">Numéro : {selectedDocument.numero}</p>
                <p className="text-muted">
                  Domaines :{" "}
                  {selectedDocument.domaines.map((d) => d.libelle).join(", ")}
                </p>
                <div
                  className="bg-light p-4 text-center"
                  style={{ height: "400px" }}
                >
                  <svg
                    width="64"
                    height="64"
                    fill="currentColor"
                    className="text-muted mb-3"
                    viewBox="0 0 16 16"
                  >
                    <path d="M14 4.5V14a2 2 0 0 1-2 2H4a2 2 0 0 1-2-2V2a2 2 0 0 1 2-2h5.5L14 4.5zM9.5 3A1.5 1.5 0 0 0 11 4.5h2V14a1 1 0 = 1-1 1H4a1 1 0 0 1-1-1V2a1 1 0 0 1 1-1h5.5v2z" />
                  </svg>
                  <p>Aperçu du document PDF</p>
                </div>
              </div>
            )}
          </div>
          <div className="modal-footer">
            <button
              type="button"
              className="btn btn-secondary"
              onClick={() => setShowModal(false)}
            >
              Fermer
            </button>
            {selectedDocument && selectedDocument.source ? (
              <a
                href={selectedDocument.source}
                target="_blank"
                rel="noopener noreferrer"
                className="btn btn-cta"
              >
                Télécharger
              </a>
            ) : (
              <button type="button" className="btn btn-secondary" disabled>
                Télécharger (lien non disponible)
              </button>
            )}
          </div>
        </div>
      </div>
    </div>
  );

  const renderContent = () => {
    switch (activeSection) {
      case "accueil":
        return renderAccueil();
      case "veille":
        return renderVeille();
      case "alertes":
        return renderAlertes();
      case "profil":
        return renderProfil();
      default:
        return renderAccueil();
    }
  };

  return (
    <>
      <div className="dashboard-container">
        {notification.message && (
          <div
            className={`fixed top-4 left-1/2 -translate-x-1/2 p-4 rounded-lg shadow-lg text-white z-50 transition-opacity duration-500 ${
              notification.type === "success" ? "bg-green-500" : "bg-red-500"
            }`}
            role="alert"
            style={{ opacity: notification.message ? 1 : 0 }} // Contrôle l'opacité pour l'animation
          >
            {notification.message}
            <button
              type="button"
              className="ml-4 text-white opacity-75 hover:opacity-100"
              onClick={() => setNotification({ message: "", type: "" })}
              aria-label="Close"
            >
              &times;
            </button>
          </div>
        )}
        {renderMobileHeader()}
        {renderSidebar()}
        <div className="main-wrapper">{renderContent()}</div>
        {showModal && renderModal()}
        {showAddEntrepriseModal && renderAddEntrepriseModal()}
      </div>
    </>
  );
};

export default Dashboard;
